// SANITY CHECK LOGIC
const html = $input.item.json.data; // The page content from HTTP Request
const statusCode = $input.item.json.statusCode;

let status = "VALID";
let reason = "";

// 1. Check for Cloudflare/Blocks
if (statusCode === 403 || html.includes("cloudflare") || html.includes("security challenge")) {
  status = "BLOCKED_BY_WAF";
  reason = "Cloudflare detected";
} 

// 2. Check for "Dead" content
else if (html.length < 500) {
  status = "JUNK";
  reason = "Page too short/Empty";
}

// 3. Check for placeholders
else if (html.toLowerCase().includes("site under construction") || html.toLowerCase().includes("buy this domain")) {
  status = "JUNK";
  reason = "Domain for sale/Construction";
}

return {
  url: $input.item.json.url,
  scrapingStatus: status,
  rejectionReason: reason,
  canProceed: status === "VALID"
};
